#include <iostream>
#include <vector>

int main() {
    int baseNumber, val;
    std::cin >> baseNumber >> val;

    std::vector<int> array(100, 0);
    int pos = 0;

    while (val != 0) {
        array[pos] = val % baseNumber;
        val /= baseNumber;
        pos++;
    }

    for (int i = 0; i < array.size(); i++) {
        if (array[i] == 0 || array[i] == 1 || array[i] == -1) {
            continue;
        } else if (array[i] == baseNumber - 1) {
            array[i] -= baseNumber;
            if (i + 1 < array.size()) {
                array[i + 1] += 1;
            } else {
                // Extend the vector if needed
                array.push_back(1);
            }
        } else if (array[i] == baseNumber) {
